                b = readByte();
            }
            if (b == -1) return -1;
            int n = 0;
            while (isPrintableChar(b)) {
                if (b >= '0' && b <= '9') {
                    n = n * 10 + (b - '0');
                }
                b = readByte();
            }
            return n;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) return;

        int[] head = new int[n + 1];
