        int edgeCount = 0;

        for (int i = 0; i < n - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();

            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

