            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        int[] order = new int[n];
        int[] parent = new int[n + 1];
        boolean[] visited = new boolean[n + 1];

        int headQueue = 0;
        int tailQueue = 0;

        order[tailQueue++] = 1;
        visited[1] = true;

        while (headQueue < tailQueue) {
            int u = order[headQueue++];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    order[tailQueue++] = v;
                }
            }
        }

        int[] size = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            size[i] = 1;
        }

        int minDiff = n;

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int p = parent[u];
            if (p != 0) {
                size[p] += size[u];
                int diff = Math.abs(2 * size[u] - n);
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
        }

        System.out.println(minDiff);
    }
}
